('stockmanagement.stockItemCategoryConceptId','6d24eb6e-b42f-4706-ab2d-ae4472161f6a','The concept for stock item categories.','aab3b6ca-5ee6-4ae7-9223-849426de14f9',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('stockmanagement.stockItemSearchMaxIntermediateResult','50','Maximum intermediate results to fetch when searching for stock items that are drugs or concepts.','4efa7200-0277-4ad9-8a29-f8f9e1f136a8',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
