('stockmanagement.stockRuleJobBatchSize','1000','Number of records fetched from data store per cycle','dd471d40-e856-4d9b-a25d-42916f43ed65',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('stockmanagement.stockSourceCodeConceptId','2e1e8049-9cbe-4a2d-b1e5-8a91e5d7d97d','The code concept for stock source types.','5a2333aa-da0a-4498-bb99-cc3354f982bf',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
